<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec:java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dexec.mainClass=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.example.HelloWorld&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 运行</span></span>
